import{_ as i,o as a,c as e,a2 as n}from"./chunks/framework.CsFjlSKj.js";const c=JSON.parse('{"title":"Container Networking","description":"","frontmatter":{},"headers":[],"relativePath":"containers/5-networking.md","filePath":"containers/5-networking.md"}'),t={name:"containers/5-networking.md"};function r(o,s,h,l,p,k){return a(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="container-networking" tabindex="-1">Container Networking <a class="header-anchor" href="#container-networking" aria-label="Permalink to &quot;Container Networking&quot;">​</a></h1><p>Networking in Docker and Podman is highly configurable, allowing you to choose between maximum isolation, ease of use, or raw bare-metal performance.</p><h2 id="_1-the-bridge-network-default" tabindex="-1">1. The Bridge Network (Default) <a class="header-anchor" href="#_1-the-bridge-network-default" aria-label="Permalink to &quot;1. The Bridge Network (Default)&quot;">​</a></h2><p>When you run a container without specifying a network, it is attached to the default <code>bridge</code> network (represented by the <code>docker0</code> or <code>cni0</code> virtual interface on your host).</p><ul><li>The container receives a private IP address (e.g., <code>172.17.0.2</code>).</li><li>The container can access the internet using NAT (Network Address Translation).</li><li>External computers <strong>cannot</strong> access the container unless you explicitly map a port (e.g., <code>-p 8080:80</code>).</li></ul><h3 id="user-defined-bridges" tabindex="-1">User-Defined Bridges <a class="header-anchor" href="#user-defined-bridges" aria-label="Permalink to &quot;User-Defined Bridges&quot;">​</a></h3><p>The default bridge network is legacy and has a major flaw: <strong>containers on the default bridge cannot resolve each other by name.</strong></p><p>If you create a <em>custom</em> bridge network, Docker enables an internal DNS server, allowing containers to talk to each other using their container names!</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Create a custom bridge network</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> network</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-net</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run two containers on the new network</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --network</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-net</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --network</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-net</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alpine</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sleep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9999</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># The &#39;app&#39; container can ping the &#39;web&#39; container by name!</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ping</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span></span></code></pre></div><p><em>(Note: Docker Compose automatically creates a custom bridge network for you).</em></p><h2 id="_2-the-host-network" tabindex="-1">2. The Host Network <a class="header-anchor" href="#_2-the-host-network" aria-label="Permalink to &quot;2. The Host Network&quot;">​</a></h2><p>If you run a container with <code>--network host</code>, Docker removes the network isolation entirely. The container literally binds directly to the physical network interface of your host machine.</p><ul><li><strong>Pros:</strong> Maximum performance. There is zero NAT overhead. Ideal for high-throughput databases or load balancers.</li><li><strong>Cons:</strong> No isolation. If the container listens on port 80, it binds to port 80 on the host machine. You cannot run two containers listening on port 80 using the host network.</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --network</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> host</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span></span></code></pre></div><h2 id="_3-the-macvlan-network" tabindex="-1">3. The Macvlan Network <a class="header-anchor" href="#_3-the-macvlan-network" aria-label="Permalink to &quot;3. The Macvlan Network&quot;">​</a></h2><p>If you want a container to appear as a physical device on your real-world router (e.g., your home router at <code>192.168.1.1</code>), you can use the <code>macvlan</code> driver.</p><p>Macvlan assigns a unique, real MAC address to the container, and your physical router will assign it a real IP address on your physical subnet (e.g., <code>192.168.1.50</code>).</p><ul><li><strong>Pros:</strong> The container acts like a completely separate physical computer on your LAN.</li><li><strong>Cons:</strong> Complex to set up, and due to security restrictions in the Linux kernel, the host machine cannot directly ping its own macvlan containers.</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Example Macvlan creation (requires defining your physical subnet)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> network</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> macvlan</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --subnet=192.168.1.0/24</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --gateway=192.168.1.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> parent=eth0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pub_net</span></span></code></pre></div><h2 id="_4-the-none-network" tabindex="-1">4. The None Network <a class="header-anchor" href="#_4-the-none-network" aria-label="Permalink to &quot;4. The None Network&quot;">​</a></h2><p>For maximum security workloads (e.g., a container whose only job is to encrypt files read from a mounted volume), you can completely disable networking. The container will only have a <code>loopback</code> interface (<code>127.0.0.1</code>).</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --network</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> none</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alpine</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sleep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9999</span></span></code></pre></div>`,22)])])}const g=i(t,[["render",r]]);export{c as __pageData,g as default};
